# ===== تابع محاسبه راندمان کارخانه فب نیمه‌هادی (متناسب با قدرت فناورانه کشور) =====
def get_chip_fab_effect(country_key: str) -> dict:
    """محاسبه خروجی تولید روزانه تراشه و درآمد کارخانه فب نیمه‌هادی به ازای هر واحد."""
    fab_rates = {
        # Tier S: ابرقدرت‌های تراشه (تایوان و کره جنوبی)
        "taiwan": 400, "south_korea": 400,
        # Tier A: غول‌های طراحی و تجهیزات لیتوگرافی (آمریکا، هلند، ژاپن)
        "usa": 300, "netherlands": 300, "japan": 300,
        # Tier B: قطب‌های صنعتی پیشرفته
        "china": 180, "germany": 180, "singapore": 180, "uk": 180,
        "france": 180, "israel": 180, "switzerland": 180,
        # Tier C: کشورهای صنعتی و منطقه‌ای
        "russia": 75, "india": 75, "iran": 75, "turkey": 75, "poland": 75,
        "brazil": 75, "canada": 75, "australia": 75, "sweden": 75, "italy": 75,
        "spain": 75, "malaysia": 75, "vietnam": 75, "philippines": 75,
        "mexico": 75, "ukraine": 75, "norway": 75, "finland": 75, "indonesia": 75, "pakistan": 75,
    }
    rate = fab_rates.get(country_key, 25)
    return {"income": 850_000, "chips_daily": rate}


def get_equipment_chips_req(item: dict) -> int:
    """محاسبه تراشه‌های پردازشی مورد نیاز جهت ساخت هر واحد تجهیز نظامی های‌تک."""
    if not item:
        return 0
    
    # Explicit override if defined
    if "chips_req" in item:
        return int(item["chips_req"])

    cat = item.get("category", "")
    key = str(item.get("key") or item.get("equipment_key") or "").lower()
    name = str(item.get("name") or item.get("equipment_name") or "").lower()
    price = item.get("price") or item.get("buy_price") or 0

    # 1. جنگنده‌های نسل ۵ و بمب‌افکن‌های پنهانکار
    if any(k in key or k in name for k in ["f35", "f-35", "su57", "su-57", "j20", "j-20", "f22", "f-22", "b2", "b-2", "b21", "kf21"]):
        return 8

    # 2. جنگنده‌های نسل ۴.۵ و ۴ و آواکس و جنگ الکترونیک
    if cat == "Aircraft":
        if any(k in key or k in name for k in ["f15", "f-15", "f16", "f-16", "f18", "f-18", "rafale", "رافال", "typhoon", "تایفون", "gripen", "گریپن", "su35", "su-35", "su30", "su34", "mig35", "j16", "j10", "globaleye", "awacs", "shavit", "g550"]):
            return 4
        if price >= 10_000_000:
            return 3
        if price >= 3_000_000:
            return 2
        return 1

    # 3. موشک‌های بالستیک، هایپرسونیک و کروز دوربرد
    if cat == "Missiles":
        if any(k in key or k in name for k in ["hypersonic", "هایپرسونیک", "fattah", "فتاح", "kinzhal", "کینژال", "zircon", "زرکون", "rampage", "icbm", "jericho", "جریکو", "sarmat", "سارمات", "khorramshahr", "خرمشهر", "sejjil", "سجیل", "df", "storm_shadow", "tomahawk", "تاماهاوک", "kalibr", "کالیبر", "popeye", "delilah", "hascon", "black_shaheen"]):
            return 2
        if price >= 1_000_000:
            return 1
        return 0

    # 4. سامانه‌های پدافند هوایی پیشرفته
    if cat == "Air Defense":
        if any(k in key or k in name for k in ["patriot", "پاتریوت", "s400", "s-400", "s300", "s-300", "iron_dome", "گنبد آهنین", "arrow", "پیکان", "davids_sling", "فلاخن", "thaad", "تاد", "bavar", "باور", "khordad", "خرداد", "pantsir", "پانتسیر", "cheongung", "iris-t", "nasams", "hq-9", "tor", "تور"]):
            return 4
        return 2

    # 5. پهپادهای انتحاری، رزمی و شناسایی پیشرفته
    if cat == "UAV":
        if any(k in key or k in name for k in ["heron", "hermes", "reaper", "predator", "mq-9", "wing_loong", "yabhon", "mohajer", "مهاجر", "karrar", "کرار", "shahed136", "شاهد-۱۳۶", "shahed131", "harpy", "harop", "hero", "shadow"]):
            return 1
        return 0

    return 0

